use vstd::prelude::*;

verus! {

fn intersperse(numbers: &[i32], delim: i32) -> (res: Vec<i32>)
    ensures
        // Length: empty stays empty; otherwise 2*n - 1
        res@.len() == if numbers@.len() == 0 { 0 } else { 2 * numbers@.len() - 1 },
        // Content: even positions are original elements; odd positions are delim
        forall|k: int|
            0 <= k && k < res@.len() ==> (
                if k % 2 == 0 {
                    res@[k] == numbers@[k / 2]
                } else {
                    res@[k] == delim
                }
            ),
{
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }

    let mut res = Vec::with_capacity(2 * n - 1);

    for (i, &x) in numbers.iter().enumerate()
        invariant
            0 <= i <= numbers@.len(),
            // After processing i elements, res has length 2*i - 1 (for i>0) or 0 (for i==0)
            res@.len() == if i == 0 { 0 } else { 2 * i - 1 },
            // Partial correctness for prefix up to current res length
            forall|k: int|
                0 <= k && k < res@.len() ==> (
                    if k % 2 == 0 {
                        res@[k] == numbers@[k / 2]
                    } else {
                        res@[k] == delim
                    }
                ),
        decreases numbers@.len() - i
    {
        if i > 0 {
            res.push(delim);

            // After pushing delim, the last index is odd and equals delim
            assert(res@.len() == 2 * i);
            assert(res@[res@.len() as int - 1] == delim);
        }

        res.push(x);

        // After pushing x, the last index is even and equals numbers[i]
        assert(res@.len() == 2 * i + 1);
        assert(res@[res@.len() as int - 1] == numbers@[i as int]);
    }

    res
}

} // verus!